{
  "aggregate_id": "DEF-NRS-484B-018::electric_scooter",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes human-powered devices, which the required definition of vehicle expressly excepts."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "Neither the many-passenger design in the contract nor the quoted weight limit establishes that every member weighs more than 100 pounds without riders."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The pedestrian contract permits a child in a motorized wheelchair, and the posted words do not settle that wheelchair's relevant equipment, weight, or speed."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract permits membership through commercial licensing alone and supplies no numerical commercial-mass threshold establishing a class-wide conflict with the 100-pound limit."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The vehicle definition expressly excepts electric bicycles, and the jurisdiction's electric-bicycle definition expressly disclaims electric scooters."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "contradicted",
      "reason": "The required vehicle definition expressly excepts 'An electric scooter,' and the additional numerical requirements do not negate that class-naming exception."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation neither establishes the scooter's technical requirements nor supplies an exception removing the class."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The fire-fighting function in the contract establishes no minimum weight that conflicts with the quoted 100-pound limit."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The contract follows the jurisdiction's moped classification, whose posted definition expressly excludes electric scooters."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Even with separately classified powered two-wheelers removed, the contract leaves other configurations and their compliance with the scooter's technical limits unsettled."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The astride two- or three-wheel configuration neither establishes nor precludes the required electric equipment, weight, and speed, and no posted motorcycle-specific exception settles the class."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official or contracted road service neither establishes the scooter's technical requirements nor constitutes a posted exception."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The human-power and assistive-mobility exceptions do not exhaust the contract's motorized-wheelchair possibilities, whose scooter-specific properties remain unspecified."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The cane, guide-animal, or escort condition does not resolve the motorized-wheelchair possibilities permitted by the pedestrian contract."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The contract's description of on-track equipment does not establish exclusive use upon stationary rails, as the quoted exception requires."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School-child transport and jurisdictional markings establish no minimum unladen weight exceeding the quoted limit."
    },
    {
      "class": "ru.taxicab",
      "verdict": "supported",
      "reason": "Marked passenger service for hire neither determines the required equipment, weight, and speed nor triggers a posted class-specific exception."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "Tour or shuttle service and a lengthened passenger body establish no class-wide minimum weight above 100 pounds."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "The contract does not forbid auxiliary motor or rider propulsion, and the quoted words impose no express single-unit restriction."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public-transit service, livery, and route displays establish no minimum weight conflicting with the quoted limit."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A body built for carrying goods establishes no minimum unladen weight above 100 pounds."
    }
  ]
}

